import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-01-08:: Ceph DocUBetter Meeting","description":"","frontmatter":{"title":"2020-01-08:: Ceph DocUBetter Meeting","date":"2020-01-08T00:00:00.000Z","updated":"2020-01-11T00:00:00.000Z","tags":["Ceph","文档更新","文档审查","Rados命令","文档管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-08_-_-_Ceph_DocUBetter_Meeting.md","filePath":"posts/2020/2020-01-08_-_-_Ceph_DocUBetter_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-01-08_-_-_Ceph_DocUBetter_Meeting.md"};function o(n,a,h,s,d,u){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><p>2020年1月初</p><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>会议主持人未明确提及，但提到了Brad和David。</li><li>其他参会人员包括Patrick、John Wilkins、Kafer等，具体角色未详细说明。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph文档更新</strong></p><ul><li>完成了Ceph入门指南的PR，感到松了一口气。</li><li>讨论了使用Rados命令存储和检索文件的计划，以及与Brad合作编写Rados速查表的计划。</li><li>提到了12月11日的会议记录被意外翻译成中文的问题，正在调查原因。</li></ul></li><li><p><strong>文档管理和更新</strong></p><ul><li>讨论了文档版本管理的问题，特别是旧文档的处理，建议从最近的两个版本开始处理。</li><li>提到了CloudStack文档的更新问题，建议只关注近期的更新。</li></ul></li><li><p><strong>文档审查流程</strong></p><ul><li>讨论了文档PR的审查流程，建议关注标记为“review required”的PR，并根据需要请求其他人的审查。</li><li>提到了一些技术性较强的文档，建议由专业人员进行审查。</li></ul></li><li><p><strong>个人健康状况</strong></p><ul><li>提到了即将进行的医院检查，可能涉及紧急手术，但预计不会影响工作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>将继续处理Ceph文档的更新和审查工作。</li><li>将开始清理旧的文档PR，重点关注近两年的更新。</li><li>将根据需要请求专业人员的文档审查。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>与Brad合作编写Rados速查表。</li><li>清理和更新旧的文档PR，重点关注近两年的更新。</li><li>根据需要请求专业人员的文档审查。</li><li>如有紧急手术，将及时通知团队。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了澳大利亚的森林火灾情况，以及对当地居民的影响。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论完所有议题后结束，主持人感谢大家的参与，并祝愿医院检查顺利。</p><h4 id="修正与补充" tabindex="-1">修正与补充 <a class="header-anchor" href="#修正与补充" aria-label="Permalink to &quot;修正与补充&quot;">​</a></h4><ul><li>原总结中未提及12月11日会议记录被翻译成中文的问题，以及后续的调查情况。</li><li>原总结中未提及与Brad合作编写Rados速查表的计划。</li><li>原总结中未提及关于文档审查流程的具体讨论。</li><li>原总结中未提及关于个人健康状况的讨论。</li></ul>',17)])])}const p=e(r,[["render",o]]);export{c as __pageData,p as default};
